import { useEffect, useState } from 'react'

import { KickMessage, KickMessages, kickMessages } from '../lib/kick'

import { IonContent, IonItem, IonItemDivider, IonItemGroup, IonLabel, IonList, IonListHeader, IonNote } from '@ionic/react'


export function Sessions() {
    const [sessions, setSessions] = useState<KickMessage[][]>([])

    useEffect(() => {
        async function kick() {
            const response = await kickMessages()

            if (response.type === 'messages') {
                const messages = response.messages
                const sessions: KickMessage[][] = []
                let session: KickMessage[] | null = null

                messages.forEach(m => {
                    if (session === null || m.sequence === 0) {
                        session = []

                        sessions.push(session)
                    }

                    session.push(m)
                })

                setSessions(sessions.reverse())
            }
        }

        kick()
    }, [setSessions])

    function colorForRole(role: string) {
        if (role.toLowerCase().startsWith('system'))
            return '#339966'

        if (role.toLowerCase().startsWith('user'))
            return '#ffaa11'

        return '#eeeedd'
    }
